using Wip.Bones.Domain;
using Wip.Bones.Engine;
using System.Collections.Generic;
using System.Linq;

public sealed class SeatStrategy : IBonesPlayerSlot
{
    public BonesMove ChooseMove(BonesRoundState state, IReadOnlyList<BonesMove> legalMoves)
    {
        if (legalMoves.Count == 0)
            throw new System.InvalidOperationException("No legal moves.");

        var board = state.Board;
        var hand = state.Hands.GetHand(state.CurrentPlayer);
        int leftEndPip = board.LeftEnd?.Pip.Value ?? -1;
        int rightEndPip = board.RightEnd?.Pip.Value ?? -1;

        // Count pip frequencies in hand
        int[] pipCounts = new int[7];
        foreach (var t in hand.Tiles)
        {
            pipCounts[t.LowPip.Value]++;
            if (!t.IsDouble)
                pipCounts[t.HighPip.Value]++;
        }

        int handTileCount = hand.Tiles.Length;
        bool isEndgame = handTileCount <= 3;

        BonesMove? bestMove = null;
        int bestScore = int.MinValue;

        foreach (var move in legalMoves)
        {
            if (move.IsPass)
            {
                if (bestMove == null)
                {
                    bestMove = move;
                    bestScore = -10000;
                }
                continue;
            }

            var tile = move.Tile!.Value;
            int score = 0;

            // Strong bonus for doubles: blocking power and flexibility
            if (tile.IsDouble)
                score += 60;

            // Prefer high total pips to shed large tiles
            score += tile.TotalPips * 3;

            // Check if tile matches board ends
            bool matchesLeft = leftEndPip >= 0 && (tile.LowPip.Value == leftEndPip || tile.HighPip.Value == leftEndPip);
            bool matchesRight = rightEndPip >= 0 && (tile.LowPip.Value == rightEndPip || tile.HighPip.Value == rightEndPip);

            // Strong preference for moves that match a board end
            if (matchesLeft || matchesRight)
                score += 60;
            else if (board.Tiles.Length > 0)
                score -= 80;

            // Prefer playing on the side that matches our stronger pip holdings
            if (matchesLeft)
            {
                int leftPipCount = pipCounts[leftEndPip];
                score += leftPipCount * 7;
                if (move.Side == BonesBoardSide.Left)
                    score += 15;
            }
            if (matchesRight)
            {
                int rightPipCount = pipCounts[rightEndPip];
                score += rightPipCount * 7;
                if (move.Side == BonesBoardSide.Right)
                    score += 15;
            }

            // Avoid playing a tile that would leave us with no matching ends
            if (leftEndPip >= 0 || rightEndPip >= 0)
            {
                int remainingMatching = CountMatchingAfterPlay(hand, tile, leftEndPip, rightEndPip);
                if (remainingMatching == 0)
                    score -= 100;
            }

            // Bonus for playing a tile that matches pips we hold many of (future options)
            int lowPipCount = pipCounts[tile.LowPip.Value];
            int highPipCount = tile.IsDouble ? 0 : pipCounts[tile.HighPip.Value];
            score += (lowPipCount + highPipCount) * 5;

            // Prefer playing on the side that balances chain length
            if (matchesLeft && matchesRight)
            {
                int leftChainCount = 0, rightChainCount = 0;
                foreach (var chainTile in board.Tiles)
                {
                    if (chainTile.ChainLeftPip.Value == leftEndPip)
                        leftChainCount++;
                    if (chainTile.ChainRightPip.Value == rightEndPip)
                        rightChainCount++;
                }
                if (leftChainCount < rightChainCount && move.Side == BonesBoardSide.Left)
                    score += 20;
                else if (rightChainCount < leftChainCount && move.Side == BonesBoardSide.Right)
                    score += 20;
            }

            // Penalty for playing a double that would make us vulnerable to being blocked
            if (tile.IsDouble)
            {
                int otherPip = tile.LowPip.Value;
                if (pipCounts[otherPip] >= 3)
                    score -= 30;
            }

            // Endgame awareness: prefer to keep matching ends when hand is small
            if (isEndgame && (matchesLeft || matchesRight))
            {
                int remainingMatchingAfterPlay = CountMatchingAfterPlay(hand, tile, leftEndPip, rightEndPip);
                if (remainingMatchingAfterPlay > 0)
                    score += 25;
            }

            // Prefer playing tiles that match the same pip as our smallest hand count (to increase blocking)
            if (matchesLeft && matchesRight)
            {
                int leftPipCount = pipCounts[leftEndPip];
                int rightPipCount = pipCounts[rightEndPip];
                if (leftPipCount < rightPipCount)
                    score += 5;
            }

            // Slightly prefer playing on the side that has been played less (to balance board)
            if (matchesLeft || matchesRight)
            {
                int leftSidePlayed = 0;
                int rightSidePlayed = 0;
                foreach (var chainTile in board.Tiles)
                {
                    if (chainTile.ChainLeftPip.Value == leftEndPip)
                        leftSidePlayed++;
                    if (chainTile.ChainRightPip.Value == rightEndPip)
                        rightSidePlayed++;
                }
                if (matchesLeft && leftSidePlayed < rightSidePlayed)
                    score += 10;
                else if (matchesRight && rightSidePlayed < leftSidePlayed)
                    score += 10;
            }

            // Avoid playing the same pip repeatedly on same side to prevent blocking self
            if (matchesLeft)
            {
                int leftSamePipCount = 0;
                foreach (var chainTile in board.Tiles)
                {
                    if (chainTile.ChainLeftPip.Value == leftEndPip && 
                        (chainTile.Tile.LowPip.Value == leftEndPip || chainTile.Tile.HighPip.Value == leftEndPip))
                        leftSamePipCount++;
                }
                if (leftSamePipCount >= 3)
                    score -= 40;
            }
            if (matchesRight)
            {
                int rightSamePipCount = 0;
                foreach (var chainTile in board.Tiles)
                {
                    if (chainTile.ChainRightPip.Value == rightEndPip && 
                        (chainTile.Tile.LowPip.Value == rightEndPip || chainTile.Tile.HighPip.Value == rightEndPip))
                        rightSamePipCount++;
                }
                if (rightSamePipCount >= 3)
                    score -= 40;
            }

            // Prefer playing on the side that matches the pip we have fewer of (to create balance and avoid blocking)
            if (matchesLeft && matchesRight)
            {
                int leftPipCount = pipCounts[leftEndPip];
                int rightPipCount = pipCounts[rightEndPip];
                if (leftPipCount < rightPipCount && move.Side == BonesBoardSide.Left)
                    score += 8;
                else if (rightPipCount < leftPipCount && move.Side == BonesBoardSide.Right)
                    score += 8;
            }

            // In endgame, prefer playing tiles that reduce hand total significantly
            if (isEndgame)
            {
                score += tile.TotalPips * 2;
            }

            // Penalty for playing a double when we have a very unbalanced hand (many of one pip)
            if (tile.IsDouble)
            {
                int maxPipCount = 0;
                for (int i = 0; i < 7; i++)
                {
                    if (pipCounts[i] > maxPipCount)
                        maxPipCount = pipCounts[i];
                }
                if (maxPipCount >= 4)
                    score -= 25;
            }

            // NEW: Prefer playing a tile that matches the end with fewer remaining matching tiles in hand
            // This helps maintain board control and avoid being forced to pass
            if (matchesLeft && matchesRight)
            {
                int leftHandCount = pipCounts[leftEndPip];
                int rightHandCount = pipCounts[rightEndPip];
                if (move.Side == BonesBoardSide.Left && leftHandCount <= rightHandCount)
                    score += 12;
                else if (move.Side == BonesBoardSide.Right && rightHandCount <= leftHandCount)
                    score += 12;
            }
            else if (matchesLeft)
            {
                int leftHandCount = pipCounts[leftEndPip];
                if (leftHandCount <= 2)
                    score += 10; // Play on left if we have few of that pip to avoid getting stuck
            }
            else if (matchesRight)
            {
                int rightHandCount = pipCounts[rightEndPip];
                if (rightHandCount <= 2)
                    score += 10; // Play on right if we have few of that pip to avoid getting stuck
            }

            if (score > bestScore)
            {
                bestScore = score;
                bestMove = move;
            }
        }

        if (bestMove == null)
        {
            var fingerprint = System.HashCode.Combine(-1002546856, 4, state.CurrentPlayer.Seat, legalMoves.Count);
            var index = (fingerprint & int.MaxValue) % legalMoves.Count;
            return legalMoves[index];
        }

        return bestMove;
    }

    private int CountPipInHand(BonesHand hand, int pip)
    {
        int count = 0;
        foreach (var tile in hand.Tiles)
        {
            if (tile.LowPip.Value == pip)
                count++;
            if (tile.HighPip.Value == pip)
                count++;
        }
        return count;
    }

    private int CountMatchingAfterPlay(BonesHand hand, BonesTile playedTile, int leftPip, int rightPip)
    {
        int count = 0;
        foreach (var tile in hand.Tiles)
        {
            // Skip the tile we're playing (compare by identity)
            if (tile.LowPip.Value == playedTile.LowPip.Value && 
                tile.HighPip.Value == playedTile.HighPip.Value && 
                tile.IsDouble == playedTile.IsDouble)
                continue;

            if (leftPip >= 0 && (tile.LowPip.Value == leftPip || tile.HighPip.Value == leftPip))
                count++;
            if (rightPip >= 0 && (tile.LowPip.Value == rightPip || tile.HighPip.Value == rightPip))
                count++;
        }
        return count;
    }
}
